#!/usr/bin/env bash
# podread_boxfuse10k.sh -- pod-side read of card PREREG_V8F_PROOF_ADD131 (BOXFUSE10K). CPU only (CUDA_VISIBLE_DEVICES=-1 is set here), no rollout.
# Generated by make_boxfuse_reader.py from the driver of card ADD117. Stage controls: needs the done marker of the rollout queue of this card and no stop marker, links the new run names (both seeds)
#   and the banked runs of the two settings (and the spread run) into the pull folder of the readers, runs the selftest of the source reader of card ADD114 from its own kit folder first, then
#   read_boxfuse10k.py --stage controls (writes $OUT/BOXFUSE10K_CONTROLS.json). The time arguments of the tests control are filled here with stat -c %Y (the two lead test outputs in $GE/lead_tests),
#   the first token of the first line of BOXFUSE10K_START.txt (`<epoch seconds> <ISO time>Z pid <pid>`) and date +%s at the start of the stage.
# Stage names: read_boxfuse10k.py --stage names on that controls file (the reader refuses unless all ten controls pass and its inputs are unchanged), writes $OUT/BOXFUSE10K_RESULT.json,
#   $OUT/BOXFUSE10K_VERDICT.md, $OUT/read_names.log and $OUT/read_names.out.
# The ten controls print as `ctl j0` to `ctl j9`; they are the controls j0 to j9 of card ADD131. The stage controls prints no level, no difference and no name. Never reads twice into one file.
# It deletes, moves and stops nothing.
# Usage: bash podread_boxfuse10k.sh controls|names
# Prints only the lines ctl j<k> PASS|FAIL <reason>, the reader's last line and: ZZ POD-BOXFUSE10K <mode> DONE rc <n> <time>   (or ZZ POD-BOXFUSE10K STOP <why>).
set -u
STAGE=${1:-}
V=/workspace/v8proof; W=$V/integ10k; P=$V/podread; RD=$P/root/integ10k; PL=$RD/pull; CODE=$P/code
GE=$V/boxfuse10k; K=$GE/kit_read; OUT=$GE/read_out; LT=$GE/lead_tests; GFM=$GE/gapfiles; K114=$V/presattr/kit_read
CS=$V/cropscale; CHK=$V/visrule10k/check_v
MODEL=$CS/kit_read/read_cropscale10k.py
GJ=$GFM/VGAPJE.npz
GJ90=$GFM/VGAPJE90.npz
GREC=$GFM/BOXFUSE10K_GAPFILES_RECORD.json
PINNED=$V/hierrep/pins/eval_grid_windows.json
JOIN=$V/hierrep/pins/join_eval141.npz
PY=/workspace/venv/bin/python
WRAP=$W/build/v8f_t1_eval_reader_rule_rzgfhqetjv.py
ts() { date -u +%H:%M:%SZ; }
stop() { echo "ZZ POD-BOXFUSE10K STOP $*"; exit 3; }
case "$STAGE" in controls|names) ;; *) stop "usage: controls|names";; esac
export HEADWAY_Q3DIR=$CODE/q3 HIERREP_STAGEB=$CODE/stageB TANITEVAL_ROOT=$CODE/tev HEADWAY_JOIN=$P/data/join_eval141.npz HEADWAY_BANK=$P/data/frames.npz SR_ESTREAD_DIR=$RD
export CUDA_VISIBLE_DEVICES=-1 OMP_NUM_THREADS=2 MKL_NUM_THREADS=2 OPENBLAS_NUM_THREADS=2 PYTHONIOENCODING=utf-8 PYTHONDONTWRITEBYTECODE=1
mm=$(cat /sys/fs/cgroup/memory.max); an=$(awk '/^anon /{print $2}' /sys/fs/cgroup/memory.stat)
if [ "$mm" != max ]; then free_gb=$(( (mm - an) / 1073741824 )); [ "$free_gb" -ge 20 ] || stop "MEMORY free ${free_gb} GB"; fi
for f in "$K/read_boxfuse10k.py" "$K114/read_presattr10k.py" "$MODEL"; do [ -f "$f" ] || stop "MISSING-KIT-FILE $f"; done
MODS="read_estclose10k_n2.py read_handsrc_decomp.py read_closrc10k.py read_agedose_decomp.py read_agerule_decomp.py read_longroll10k.py read_longroll10k_n3.py read_longroll10k_n4.py strat_roll_read.py"
for m in $MODS; do [ -f "$RD/$m" ] || stop "MISSING-INPUT $RD/$m"; done
if [ "$STAGE" = controls ]; then
  CSTART=$(date +%s)
  [ -f "$GE/BOXFUSE10K_DONE.txt" ] || stop "QUEUE-NOT-DONE"
  [ -e "$GE/BOXFUSE10K_STOP.txt" ] && stop "QUEUE-STOPPED"
  [ -f "$GE/BOXFUSE10K_START.txt" ] || stop "NO-START-MARKER"
  [ -e "$OUT/BOXFUSE10K_CONTROLS.json" ] && stop "ALREADY-READ controls"
  for f in "$LT/lead_pytest_queue.out" "$LT/lead_pytest_read.out" "$PINNED" "$GJ" "$GJ90" "$GREC" "$CHK/CHECK_WRAPPER_V_DONE.txt" "$CHK/CHECK_WRAPPER_V.hashes" "$JOIN" "$WRAP"; do
    [ -f "$f" ] || stop "MISSING-INPUT $f"
  done
  for x in I10RQ50KF5Hb20gJEc I10RQ50KF5Hb20gJA90 I10RQ50KF5Hb20gGEc I10RQ50KF5Hb20gA90 I10RLcKF5Hb20 I10RQ50KF5Hb20 I10RQ50Hb20gJEc I10RQ50Hb20gGEc I10RLcHb20 I10RQ50Hb20 I10R0Hb20; do
    for s in 0 1; do
      d=$W/t1/${x}_s$s; [ -f "$d/T1_DONE" ] || stop "MISSING-RUN $d"
      [ -e "$PL/$(basename "$d")" ] || ln -s "$d" "$PL/$(basename "$d")"
    done
  done
  mkdir -p "$OUT"
  MQ=$(stat -c %Y "$LT/lead_pytest_queue.out"); MR=$(stat -c %Y "$LT/lead_pytest_read.out")
  QS=$(head -n 1 "$GE/BOXFUSE10K_START.txt" | awk '{print $1}'); [[ "$QS" =~ ^[0-9]+$ ]] || stop "START-MARKER-UNREADABLE"
  ( cd "$RD" && sha256sum $MODS; sha256sum "$K/read_boxfuse10k.py" "$MODEL" "$LT/lead_pytest_queue.out" "$LT/lead_pytest_read.out" "$WRAP" "$GJ" "$GJ90" "$GREC" "$CHK/CHECK_WRAPPER_V_DONE.txt" "$JOIN" "$PINNED" ) > "$OUT/READER_HASHES.txt"
  ( cd "$RD" && "$PY" "$K114/read_presattr10k.py" --selftest --model-reader "$MODEL" > "$OUT/selftest_pod.log" 2>&1 ); st=$?
  tail -n 1 "$OUT/selftest_pod.log" | cut -c1-120
  [ "$st" = 0 ] || stop "SELFTEST-ON-POD rc $st"
  ( cd "$RD" && "$PY" "$K/read_boxfuse10k.py" --stage controls --model-reader "$MODEL" --pull "$PL" --code "$CODE" --grid-dir "$W/longroll" --grid-pinned "$PINNED" --w "$W" --tree "$W/tree" --wrapper-file "$WRAP" \
      --gap-file VGAPJE="$GJ" --gap-file VGAPJE90="$GJ90" --gap-record "$GREC" \
      --wrapper-check "$CHK/CHECK_WRAPPER_V_DONE.txt" --wrapper-hashes "$CHK/CHECK_WRAPPER_V.hashes" \
      --tests-queue "$LT/lead_pytest_queue.out" --tests-read "$LT/lead_pytest_read.out" --tests-mtime-queue "$MQ" --tests-mtime-read "$MR" --queue-start "$QS" --controls-start "$CSTART" \
      --done-marker "$GE/BOXFUSE10K_DONE.txt" --out "$OUT/BOXFUSE10K_CONTROLS.json" > "$OUT/read_controls.log" 2>&1 ); rc=$?
  grep -E '^ctl j[0-9] (PASS|FAIL)|^ZZ READ-BOXFUSE10K' "$OUT/read_controls.log" | cut -c1-200 | head -n 12
  echo "ZZ POD-BOXFUSE10K controls DONE rc $rc $(ts)"
else
  [ -f "$OUT/BOXFUSE10K_CONTROLS.json" ] || stop "NO-CONTROLS-FILE"
  [ -e "$OUT/BOXFUSE10K_RESULT.json" ] && stop "ALREADY-READ names"
  ( cd "$RD" && "$PY" "$K/read_boxfuse10k.py" --stage names --model-reader "$MODEL" --controls "$OUT/BOXFUSE10K_CONTROLS.json" --out "$OUT/BOXFUSE10K_RESULT.json" --verdict "$OUT/BOXFUSE10K_VERDICT.md" --log "$OUT/read_names.log" > "$OUT/read_names.out" 2>&1 ); rc=$?
  tail -n 1 "$OUT/read_names.out" | cut -c1-200
  echo "ZZ POD-BOXFUSE10K names DONE rc $rc $(ts)"
fi
